@pytest.mark.parametrize( ("text", "price"), [("offer lamp 100", 100), ("buy lamp for 100", 100), ("offer lamp 125", 125)], ) def test_first_offer_when_explicit_completes_signed_sale( monkeypatch: pytest.MonkeyPatch, text: str, price: int, ) -> None: # Given: a model must retrieve, preserve SKU and amount, and correct bad actions. _ = scripted( monkeypatch, [ action("reject", price), action("accept", price), ("search_catalog", {"query": "lamp"}), action("quote", 100), action("accept", price, "chair"), action("accept", price + 1), action("accept", price), ], ) catalog = Catalog(Path(__file__).resolve().parents[1] / "catalog.json") key = Ed25519PrivateKey.generate()
async def scenario() -> None: async with AsyncOpenAI(api_key="offline-placeholder") as model: app = create_app( "http://seller/", Harness(model, print), catalog, "Test", signer=ReceiptSigner(key), ) async with httpx2.AsyncClient( transport=httpx2.ASGITransport(app=app), base_url="http://seller", ) as client: # When: one explicit offer reaches the real A2A route. wire = await send(client, text) task = task_from(wire) replay = await send(client, str(price), task.id) # Then: exact amount is signed once and terminal replay is rejected. assert task.status.state == TaskState.TASK_STATE_COMPLETED raw = TypeAdapter(JsonValue).validate_json( MessageToJson(task.artifacts[0].parts[0].data) ) assert isinstance(raw, dict) assert raw["price"] == price receipt = SignedReceipt.model_validate( { **{ field: raw[field] for field in ("shop", "item", "task", "sig_seller") }, "price": price, } ) assert receipt.price == price assert raw["sku"] == "lamp" assert receipt.task == task.id key.public_key().verify( base64.b64decode(receipt.sig_seller), receipt.canonical() ) assert isinstance(replay, dict) assert "error" in replay print(json.dumps({"scenario": text, "wire": wire, "replay": replay}))
